-- Jeu de LecteurOrdonnancesEnrolement et EcrivainOrdonnancesEnrolement (« Ordonnance d'enrôlement », PROC_CORDJRCS), lot 5 du plan
-- « RIG v3 100 % fonctionnel » (plan-676a4b19). Identifiants 1 500 5xx a 1 500 8xx (lot 5 : 1 500 000 a 1 599 999).
-- Joue le PREMIER des jeux de ce lot, avant ceux de JOIN, LIBAFFAIRE, MJUD qui creent aussi ces tables : elles le sont a
-- l'IDENTIQUE de leur CREATE (le meme bloc que PROC_IPE.sql), puis recoivent les colonnes du lot (types de RIG_DEV, copie de dev).
-- Le code affaire du banc RC15 numerote dans la serie JRR15 : aucun autre ecran ne lit ce type de numero de role ; les parties de
-- ce jeu n'ont pas de designation (PROC_PARTIES ne lit que les parties designees).
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NATURE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NATURE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NAT_AFF_PART') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NAT_AFF_PART varchar(5) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_ACTE_PROCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_ACTE_PROCE varchar(3) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ACTE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ACTE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_SAISINE_GREFFE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_SAISINE_GREFFE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ETAT_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ETAT_INSTANCE varchar(1) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ETAT_INFO') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ETAT_INFO varchar(1) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUM_REP_GENERAL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUM_REP_GENERAL varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_AFFRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_AFFRE int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUMERO_SOURCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NOTE_AUDIENCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NOTE_AUDIENCE varchar(max) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TOP_EXPERIAN') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TOP_EXPERIAN bit NULL;
IF OBJECT_ID(N'v2.CODE_AFFAIRE') IS NULL
    CREATE TABLE v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEAFFAIR_LIBELLE_ECRAN varchar(100) NOT NULL,
        R_CODEAFFAIR_TYPE_NUM_ROLE varchar(5) NULL, R_CODEAFFAIR_TYPE_INSTANCE varchar(2) NOT NULL);
IF COL_LENGTH('v2.CODE_AFFAIRE', 'R_CODEAFFAIR_NUM_REPERTOIRE') IS NULL ALTER TABLE v2.CODE_AFFAIRE ADD R_CODEAFFAIR_NUM_REPERTOIRE bit NULL;
IF COL_LENGTH('v2.CODE_AFFAIRE', 'R_CODEAFFAIR_NAT_AFF_PART') IS NULL ALTER TABLE v2.CODE_AFFAIRE ADD R_CODEAFFAIR_NAT_AFF_PART varchar(5) NULL;
IF OBJECT_ID(N'v2.CODE_ACTE_PROCE') IS NULL
    CREATE TABLE v2.CODE_ACTE_PROCE (R_CODEACTEPR_VALEUR varchar(3) NOT NULL PRIMARY KEY, R_CODEACTEPR_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CODEACTEPR_ISO varchar(20) NOT NULL);
IF OBJECT_ID(N'v2.DOSSIER_DEMANDE') IS NULL
    CREATE TABLE v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM int NOT NULL PRIMARY KEY, DSSDM_ID_DMND int NOT NULL,
        DSSDM_CODE_SEQUENCEUR varchar(20) NOT NULL, DSSDM_VALEUR_SEQUENCEUR varchar(100) NULL);
IF OBJECT_ID(N'v2.AFFAIRE') IS NULL
    CREATE TABLE v2.AFFAIRE (AFFRE_ID_AFFRE int NOT NULL PRIMARY KEY, AFFRE_ID_UTLST_CREATION int NULL, AFFRE_ID_UTLST_EN_COURS int NULL,
        AFFRE_DATE_CREATION datetime NOT NULL, AFFRE_LIBELLE varchar(70) NULL);
IF OBJECT_ID(N'v2.PARTIE') IS NULL
    CREATE TABLE v2.PARTIE (PRT_ID_PRT int NOT NULL PRIMARY KEY, PRT_ID_INSTN int NOT NULL, PRT_NUM_ORDRE smallint NOT NULL,
        PRT_CIVILITE varchar(7) NOT NULL, PRT_DESIGNATION varchar(512) NULL, PRT_NOM varchar(512) NULL, PRT_SIREN varchar(10) NULL,
        PRT_MODE_PRESENTATION varchar(3) NULL, PRT_QUALIF_PARTIE varchar(5) NOT NULL, PRT_DATE_ACTE datetime NULL);
IF COL_LENGTH('v2.PARTIE', 'PRT_NOM') IS NULL ALTER TABLE v2.PARTIE ADD PRT_NOM varchar(512) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_EDITION_JUGEMENT') IS NULL ALTER TABLE v2.PARTIE ADD PRT_EDITION_JUGEMENT varchar(5) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_MANDATAIRE_EDITION_JUGEMENT') IS NULL ALTER TABLE v2.PARTIE ADD PRT_MANDATAIRE_EDITION_JUGEMENT varchar(5) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_MANDATAIRE_PLAI_EDITION_JUGEMENT') IS NULL ALTER TABLE v2.PARTIE ADD PRT_MANDATAIRE_PLAI_EDITION_JUGEMENT varchar(5) NULL;
IF COL_LENGTH('v2.PARTIE', 'PRT_COPIE_DECISION') IS NULL ALTER TABLE v2.PARTIE ADD PRT_COPIE_DECISION bit NULL;
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL, DCJDC_NUM_ORDRE smallint NOT NULL,
        DCJDC_DATE_PREVUE datetime NULL, DCJDC_DATE datetime NULL, DCJDC_TYPE_DECISION varchar(10) NULL);
IF COL_LENGTH('v2.DEMANDE', 'DMND_EN_COURS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_EN_COURS bit NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM_UTILISATEUR') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM_UTILISATEUR varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_ID_AFFRE') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_ID_AFFRE int NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NUM_INDICATIF') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NUM_INDICATIF varchar(14) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_LES_NUMEROS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_LES_NUMEROS varchar(128) NULL;

-- Les compteurs (num.Compteur, NUM-001) : JRR15 (« ALC », lettre RC, comme JRORC dans la copie de dev, Debut 1) ; DMD s'il manque.
EXEC sp_executesql N'
INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''JRR15'', 2026, ''ALC'', 4, ''RC'', 5, 1);
IF NOT EXISTS (SELECT 1 FROM num.Compteur WHERE Type = ''DMD'')
    INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''DMD'', 2026, ''LAQC'', 2, ''D'', 5, 1);';

-- Les references : RC15 (type RC, sans repertoire general, comme ORCS dans la copie de dev) ; IPR15 (type IP : refuse pour une
-- ordonnance RCS, OPE_INSTANCE.cs:1649-1650). Acte : S15 saisine d'office (ISO 03).
EXEC sp_executesql N'
INSERT INTO v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR, R_CODEAFFAIR_LIBELLE_ECRAN, R_CODEAFFAIR_TYPE_NUM_ROLE, R_CODEAFFAIR_TYPE_INSTANCE,
    R_CODEAFFAIR_NUM_REPERTOIRE, R_CODEAFFAIR_NAT_AFF_PART) VALUES
    (''RC15'', ''Ordonnance RCS du banc lot 5'', ''JRR15'', ''RC'', 0, ''0A''),
    (''IPR15'', ''Injonction du banc lot 5 (RC)'', ''JRR15'', ''IP'', 0, ''0A'');
INSERT INTO v2.CODE_ACTE_PROCE (R_CODEACTEPR_VALEUR, R_CODEACTEPR_LIBELLE_ECRAN, R_CODEACTEPR_ISO) VALUES (''S15'', ''Saisine du banc lot 5'', ''03'');';

-- Les ordonnances : 1500501 validee (V) ; 1500502 refus (O) avec instance, demandeur et defendeur ; 1500503 reclamation (N) avec
-- son instance seule ; 1500504 interrompue (I) sans instance ; 1500505 supprimee (X) : ecartee -- jumeau retenu : 1500504.
EXEC sp_executesql N'
INSERT INTO v2.DEMANDE (DMND_ID_DMND, DMND_NUM_DEMANDE, DMND_ETAT_DEMANDE, DMND_CODE_PROSS, DMND_EN_COURS, DMND_ID_AFFRE, DMND_DATE_CREATION) VALUES
    (1500501, ''D2615000501'', ''V'', ''CORDJRCS'', 0, 1500601, ''20260302''),
    (1500502, ''D2615000502'', ''O'', ''CORDJRCS'', 0, 1500602, ''20260303''),
    (1500503, ''D2615000503'', ''N'', ''CORDJRCS'', 0, 1500603, ''20260304''),
    (1500504, ''D2615000504'', ''I'', ''CORDJRCS'', 0, 1500604, ''20260305''),
    (1500505, ''D2615000505'', ''X'', ''CORDJRCS'', 0, 1500605, ''20260306'');
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_CODE_AFFAIRE, INSTN_DATE_SAISINE_GREFFE, INSTN_ID_AFFRE, INSTN_TYPE_INSTANCE) VALUES
    (1500701, ''2026RC15701'', ''ORD ALPHA # ORD BETA'', ''RC15'', ''20260302'', 1500601, ''RC''),
    (1500702, ''2026RC15702'', ''ORD GAMMA # ORD DELTA'', ''RC15'', ''20260303'', 1500602, ''RC''),
    (1500703, ''2026RC15703'', ''ORD EPSILON'', ''RC15'', ''20260304'', 1500603, ''RC'');';
INSERT INTO v2.PARTIE (PRT_ID_PRT, PRT_ID_INSTN, PRT_NUM_ORDRE, PRT_CIVILITE, PRT_DESIGNATION, PRT_QUALIF_PARTIE) VALUES
    (1500801, 1500702, 1, 'PM', NULL, 'D'), (1500802, 1500702, 1, 'PM', NULL, 'F');
